import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';

const $=s=>document.querySelector(s), gameRoot=$('#game');
const runners=[
 {name:'VEXA',title:'RIFT RUNNER',icon:'🦊',color:0xff5d9c,accent:0xffb3d2,attack:'Nova bolts',super:'NOVA BURST',desc:'Quick shots · balanced · blink dash',hp:100,speed:8.2,rate:.27,damage:21,style:'blast'},
 {name:'MOSS',title:'WILDWARDEN',icon:'🐸',color:0x9be75a,accent:0xe1ff9f,attack:'Thorn volley',super:'BRAMBLE CROWN',desc:'Heavy thorns · sturdy · root snare',hp:135,speed:6.5,rate:.48,damage:31,style:'root'},
 {name:'ZIPP',title:'VOLT SPRITE',icon:'🤖',color:0x5de6ee,accent:0xb4ffff,attack:'Arc needles',super:'CHAIN REACTION',desc:'Rapid fire · nimble · lightning chain',hp:90,speed:9,rate:.16,damage:13,style:'chain'}
];
const modes=[['SOLO','Last one standing'],['DUO','2v2 skirmish'],['SQUAD','Team arena'],['CHAOS','Rift every 7s']];
let runnerIndex=0,modeIndex=0,started=false,paused=false,soundOn=true,renderer,scene,camera,clock;
let player,enemies=[],bullets=[],fx=[],obstacles=[],bushes=[],pickups=[],portals=[],keys={},mouseDown=false,aimPoint=new THREE.Vector3(0,0,-1),touchFire=false;
let elapsed=0,riftAt=10,riftWarn=false,rifts=0,kills=0,streak=0,charge=0,playerHealth=100,dashReady=0,shootAt=0,spawnTimer=0,arenaRadius={x:14,z:10};
let soundCtx=null,joystick={x:0,z:0,pointer:null,origin:null};
const mat=(color,rough=.72,metal=0)=>new THREE.MeshStandardMaterial({color,roughness:rough,metalness:metal});
const mats={floor:mat(0x252044),tile1:mat(0x342c5a),tile2:mat(0x2c264e),wall:mat(0x4e3a79),gold:mat(0xffc66e,.38,.28),cyan:mat(0x59e6ee,.35,.3),pink:mat(0xff5f9e,.4,.15),bush:mat(0x509c62),crate:mat(0xc77652),rock:mat(0x66618d)};
function makeRenderer(){renderer=new THREE.WebGLRenderer({antialias:true,alpha:false});renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.15;gameRoot.appendChild(renderer.domElement);scene=new THREE.Scene();scene.background=new THREE.Color(0x100d2b);scene.fog=new THREE.Fog(0x100d2b,24,52);camera=new THREE.PerspectiveCamera(42,innerWidth/innerHeight,.1,100);camera.position.set(0,21,24);camera.lookAt(0,0,0);clock=new THREE.Clock();scene.add(new THREE.HemisphereLight(0xbcb2ff,0x44385e,2));const sun=new THREE.DirectionalLight(0xffedda,3.2);sun.position.set(-7,17,8);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=-22;sun.shadow.camera.right=22;sun.shadow.camera.top=20;sun.shadow.camera.bottom=-20;scene.add(sun);const fill=new THREE.PointLight(0x7258ff,32,28);fill.position.set(3,8,-4);scene.add(fill);}
function box(w,h,d,material,x,y,z,group=scene){const m=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),material);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;group.add(m);return m;}
function sphere(r,material,x,y,z,group=scene,scale=null){const m=new THREE.Mesh(new THREE.SphereGeometry(r,18,14),material);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;if(scale)m.scale.set(...scale);group.add(m);return m;}
function buildArena(){const floor=new THREE.Mesh(new THREE.PlaneGeometry(34,26),mats.floor);floor.rotation.x=-Math.PI/2;floor.receiveShadow=true;scene.add(floor);
 for(let x=-16;x<16;x+=2)for(let z=-12;z<12;z+=2)box(1.95,.055,1.95,((x+z)/2)%2?mats.tile1:mats.tile2,x,-.025,z);
 // Neon perimeter and chunky boundary
 for(const [w,d,x,z] of [[30,.38,0,-11],[30,.38,0,11],[.38,22,-15,0],[.38,22,15,0]]){box(w,1.1,d,mats.wall,x,.45,z);box(w,.08,d,mats.gold,x,1.03,z)}
 // Arena glyphs
 for(let i=0;i<4;i++){const a=i*Math.PI/2+Math.PI/4;const ring=new THREE.Mesh(new THREE.TorusGeometry(1.45,.055,8,48),new THREE.MeshStandardMaterial({color:i%2?0xa35cff:0x4adfe8,emissive:i%2?0x6327ad:0x127c89,emissiveIntensity:1.6}));ring.rotation.x=Math.PI/2;ring.position.set(Math.cos(a)*11,.09,Math.sin(a)*7);scene.add(ring);}
 // Center rift dais
 const dais=new THREE.Mesh(new THREE.CylinderGeometry(2.4,2.7,.28,8),mat(0x51417c,.45,.2));dais.position.y=.12;dais.receiveShadow=true;scene.add(dais);const inner=new THREE.Mesh(new THREE.CylinderGeometry(1.8,1.8,.035,48),new THREE.MeshStandardMaterial({color:0x4a2d8d,emissive:0x5425a8,emissiveIntensity:.7}));inner.position.y=.27;scene.add(inner);
 for(let i=0;i<8;i++){let a=i*Math.PI/4;const gem=new THREE.Mesh(new THREE.OctahedronGeometry(.22),mats.gold);gem.position.set(Math.cos(a)*2.65,.42,Math.sin(a)*2.65);scene.add(gem);}
 // cover, destructible crates, rock clusters
 const spots=[[-8,-5,'rock'],[-4,-7,'crate'],[5,-7,'rock'],[9,-3,'crate'],[-9,2,'crate'],[-5,6,'rock'],[4,6,'crate'],[9,4,'rock'],[-1,-8,'crate'],[1,8,'crate'],[-11,-2,'rock'],[11,1,'crate']];
 for(const [x,z,type] of spots){if(Math.abs(x)<2.7&&Math.abs(z)<2.7)continue;const isCrate=type==='crate';const group=new THREE.Group();group.position.set(x,0,z);scene.add(group);if(isCrate){const m=box(.95,.95,.95,mats.crate,0,.5,0,group);m.rotation.y=.12;box(1,.12,1,mat(0xf7a46c),0,.45,0,group);box(.12,1,.12,mat(0x9b563e),0,.5,0,group);obstacles.push({x,z,r:.78,hp:3,mesh:group,destructible:true});}else{sphere(.7,mats.rock,0,.38,0,group,[1.15,.85,.85]);sphere(.38,mat(0x7972a2),.42,.25,.18,group,[1,.8,1]);obstacles.push({x,z,r:.9,hp:Infinity,mesh:group,destructible:false});}}
 // soft-cover patches
 for(const [x,z] of [[-2,-5],[6,-1],[-7,-1],[2,5],[11,7],[-11,7]]){const g=new THREE.Group();g.position.set(x,0,z);scene.add(g);for(let n=0;n<9;n++){let px=(Math.random()-.5)*1.8,pz=(Math.random()-.5)*1.25;sphere(.34+Math.random()*.17,mats.bush,px,.3+Math.random()*.1,pz,g,[1.2,.9,1]);}bushes.push({x,z,r:1.15,mesh:g});}
 // edge beacon towers
 for(let i=0;i<4;i++){const x=i<2?-13.9:13.9,z=i%2?-9.8:9.8;const c=i%2?0x55e6ef:0xf56bba;box(.8,2,.8,mat(0x52427e),x,1,z);const lamp=new THREE.Mesh(new THREE.OctahedronGeometry(.45),new THREE.MeshStandardMaterial({color:c,emissive:c,emissiveIntensity:2}));lamp.position.set(x,2.2,z);scene.add(lamp);}
 createPortals();}
function createPortals(){for(let i=0;i<8;i++){const g=new THREE.Group();const ring=new THREE.Mesh(new THREE.TorusGeometry(.78,.075,10,40),new THREE.MeshStandardMaterial({color:i%2?0x61e8eb:0xff6fae,emissive:i%2?0x29b9c9:0xe53e9a,emissiveIntensity:1.6,transparent:true,opacity:.8}));ring.rotation.x=Math.PI/2;g.add(ring);const core=new THREE.Mesh(new THREE.CircleGeometry(.65,32),new THREE.MeshBasicMaterial({color:i%2?0x5ad9e3:0xfd63ae,transparent:true,opacity:.13,side:THREE.DoubleSide}));core.rotation.x=-Math.PI/2;core.position.y=-.02;g.add(core);g.visible=false;g.userData.ring=ring;scene.add(g);portals.push(g);}}
function makeCharacter(def,isPlayer=false){const g=new THREE.Group();const bodyMat=new THREE.MeshStandardMaterial({color:def.color,roughness:.48,metalness:.06});const dark=mat(0x292243);const body=sphere(.54,bodyMat,0,.76,0,g,[.86,1.05,.72]);const head=sphere(.43,bodyMat,0,1.48,.04,g,[1,.92,.9]);sphere(.13,mat(0xffffff),-.17,1.56,.39,g);sphere(.13,mat(0xffffff),.17,1.56,.39,g);sphere(.072,mat(0x241734),-.16,1.55,.5,g);sphere(.072,mat(0x241734),.18,1.55,.5,g);sphere(.09,mat(def.accent),0,1.8,.1,g);
 // ears/antennae, feet and weapon silhouette
 const earMat=bodyMat;for(let i=-1;i<=1;i+=2){const ear=new THREE.Mesh(new THREE.ConeGeometry(.15,.43,8),earMat);ear.position.set(i*.3,1.85,-.03);ear.rotation.z=i*-.35;g.add(ear);const foot=sphere(.22,dark,i*.25,.2,.08,g,[1.2,.7,1]);}
 const weapon=box(.18,.18,.78,mat(def.accent,.35,.22),.34,1.04,.55,g);weapon.rotation.x=.12;const muzzle=sphere(.13,mat(0xffffff,.25,.2),.34,1.05,.95,g,[1,.8,1]);
 const shadow=new THREE.Mesh(new THREE.CircleGeometry(.65,24),new THREE.MeshBasicMaterial({color:0x100a2b,transparent:true,opacity:.3}));shadow.rotation.x=-Math.PI/2;shadow.position.y=.015;g.add(shadow);
 const hpBg=new THREE.Mesh(new THREE.PlaneGeometry(1.1,.11),new THREE.MeshBasicMaterial({color:0x261d39,side:THREE.DoubleSide}));hpBg.position.set(0,2.3,0);g.add(hpBg);const hpFg=new THREE.Mesh(new THREE.PlaneGeometry(1,.07),new THREE.MeshBasicMaterial({color:0x83ef81,side:THREE.DoubleSide}));hpFg.position.set(0,2.3,.01);g.add(hpFg);
 const outline=new THREE.Mesh(new THREE.RingGeometry(.62,.72,32),new THREE.MeshBasicMaterial({color:isPlayer?0x5ce8ed:0xff8d7c,side:THREE.DoubleSide,transparent:true,opacity:.72}));outline.rotation.x=-Math.PI/2;outline.position.y=.035;g.add(outline);
 g.position.y=0;scene.add(g);return {group:g,body,weapon,hpFg,hpBg,hp:def.hp,maxHp:def.hp,dead:false,def,isPlayer,shoot:0,stun:0,blink:0,id:Math.random()};}
function makePlayer(){const d=runners[runnerIndex];player=makeCharacter(d,true);player.hp=player.maxHp=d.hp;playerHealth=d.hp;player.group.position.set(0,0,7);player.group.rotation.y=Math.PI;}

