function clearActors(){for(const e of enemies)scene.remove(e.group);for(const b of bullets)scene.remove(b.mesh);for(const f of fx)scene.remove(f.mesh);enemies=[];bullets=[];fx=[];if(player)scene.remove(player.group);}
function resetRound(){clearActors();elapsed=0;riftAt=modeIndex===3?6:10;riftWarn=false;rifts=0;kills=0;streak=0;charge=0;playerHealth=runners[runnerIndex].hp;dashReady=0;spawnTimer=0;started=true;paused=false;makePlayer();const count=modeIndex===0?5:modeIndex===1?5:modeIndex===2?7:6;for(let i=0;i<count;i++)spawnEnemy(i);$('#result').classList.add('hidden');$('#intro').classList.add('hidden');$('#settings').classList.add('hidden');notify('FIGHT!');updateHud();}
function playTone(freq=440,duration=.08,type='sine',volume=.035){if(!soundOn)return;try{soundCtx??=new AudioContext();const o=soundCtx.createOscillator(),g=soundCtx.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(volume,soundCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,soundCtx.currentTime+duration);o.connect(g);g.connect(soundCtx.destination);o.start();o.stop(soundCtx.currentTime+duration);}catch{}}
function notify(text){const t=$('#toast');t.textContent=text;t.classList.add('show');clearTimeout(notify.timeout);notify.timeout=setTimeout(()=>t.classList.remove('show'),1250);}
function makeBurst(pos,color=0x65e5ff,size=1){const group=new THREE.Group();group.position.copy(pos);scene.add(group);const core=new THREE.Mesh(new THREE.IcosahedronGeometry(.22*size,1),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.9}));group.add(core);const ring=new THREE.Mesh(new THREE.TorusGeometry(.35*size,.055*size,8,24),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.9}));ring.rotation.x=Math.PI/2;group.add(ring);const light=new THREE.PointLight(color,3,5);light.position.y=.2;group.add(light);fx.push({mesh:group,life:.42,max:.42,kind:'burst'});}
function makeProjectile(owner,dir,damage,style){const source=owner.group.position;const color=owner.isPlayer?owner.def.accent:0xff917c;const radius=style==='root'?.2:.13;const mesh=new THREE.Mesh(new THREE.SphereGeometry(radius,12,10),new THREE.MeshStandardMaterial({color,emissive:color,emissiveIntensity:1.6,roughness:.25}));mesh.position.set(source.x+dir.x*.95,.95,source.z+dir.z*.95);scene.add(mesh);const halo=new THREE.PointLight(color,1.3,2);mesh.add(halo);bullets.push({mesh,owner,dir:dir.clone(),speed:style==='root'?11:style==='chain'?17:15,damage,life:1.5,style});}
