function shoot(owner,target,now){if(owner.dead||now<owner.shoot)return;owner.shoot=now+owner.def.rate;const origin=owner.group.position;let dir=target.clone().sub(origin);dir.y=0;if(dir.lengthSq()<.01)return;dir.normalize();owner.group.rotation.y=Math.atan2(dir.x,dir.z);makeProjectile(owner,dir,owner.def.damage,owner.def.style);playTone(owner.isPlayer?560:260,.045,'triangle',.015);}
