function update(dt){const now=performance.now()/1000;if(started&&!paused){elapsed+=dt;if(riftWarn){for(const p of portals){p.scale.setScalar(.68+Math.sin(now*9)*.13);p.userData.ring.rotation.z+=dt*1.7;}if(elapsed>=riftAt)doRift();}else if(elapsed>=riftAt-2.5)startRiftWarning();else{$('#riftStatus').textContent=`RIFT IN ${(riftAt-elapsed).toFixed(1)}s`;}
 if(player&&!player.dead){let dx=0,dz=0;if(keys.KeyW||keys.ArrowUp)dz--;if(keys.KeyS||keys.ArrowDown)dz++;if(keys.KeyA||keys.ArrowLeft)dx--;if(keys.KeyD||keys.ArrowRight)dx++;dx+=joystick.x;dz+=joystick.z;let n=Math.hypot(dx,dz);if(n>1){dx/=n;dz/=n;}moveActor(player,dx*player.def.speed*dt,dz*player.def.speed*dt);player.group.position.y=Math.sin(now*7)*.045;if(dx||dz)player.body.rotation.z=Math.sin(now*14)*.07;else player.body.rotation.z*=.86;
 if(mouseDown||touchFire){if(touchFire||matchMedia('(pointer:coarse)').matches){const target=enemies.filter(e=>!e.dead).sort((a,b)=>a.group.position.distanceTo(player.group.position)-b.group.position.distanceTo(player.group.position))[0];if(target)aimAt(target.group.position);}shoot(player,aimPoint,now);}
 player.hpFg.scale.x=Math.max(.001,player.hp/player.maxHp);player.hpFg.position.x=-(1-player.hp/player.maxHp)*.5;player.hpBg.quaternion.copy(camera.quaternion);player.hpFg.quaternion.copy(camera.quaternion);
 }
 updateAI(dt,now);updateBullets(dt);
 if(modeIndex!==0&&modeIndex!==3&&enemies.filter(e=>!e.dead).length<3&&elapsed-spawnTimer>4){spawnEnemy(enemies.length+Math.floor(Math.random()*9));spawnTimer=elapsed;}
 if(modeIndex===0&&enemies.every(e=>e.dead))finishRound(true);
 if(elapsed>=120)finishRound(kills>=3);
 if(player){const target=new THREE.Vector3(player.group.position.x,0,player.group.position.z);camera.position.lerp(new THREE.Vector3(target.x,21,target.z+24),Math.min(1,dt*2));camera.lookAt(target);}
 updateHud();}
 for(let i=fx.length-1;i>=0;i--){const f=fx[i];f.life-=dt;const t=1-Math.max(0,f.life)/f.max;f.mesh.scale.setScalar(.5+t*2);f.mesh.children.forEach(c=>{if(c.material?.opacity!==undefined)c.material.opacity=Math.max(0,1-t);});if(f.life<=0){scene.remove(f.mesh);fx.splice(i,1);}}
