}
function frame(){requestAnimationFrame(frame);const dt=Math.min(.04,clock.getDelta());update(dt);renderer.render(scene,camera);}
function buildRoster(){const roster=$('#roster');roster.innerHTML='';runners.forEach((r,i)=>{const card=document.createElement('button');card.className='runner'+(i===runnerIndex?' selected':'');card.innerHTML=`<div class="runner-top"><div class="runner-icon" style="background:linear-gradient(145deg,#${r.color.toString(16).padStart(6,'0')},#29204f)">${r.icon}</div><div><div class="runner-name">${r.name}</div><div class="runner-role">${r.title}</div></div></div><div class="runner-attack"><b>${r.attack}</b> · ${r.desc}</div>`;card.onclick=()=>{runnerIndex=i;buildRoster();updateHud();};roster.append(card);});}
function buildModes(){const box=$('#modeList');box.innerHTML='';modes.forEach(([name,desc],i)=>{const b=document.createElement('button');b.className='mode-chip'+(i===modeIndex?' active':'');b.title=desc;b.textContent=name;b.onclick=()=>{modeIndex=i;buildModes();};box.append(b);});}
function setupInput(){const canvas=renderer.domElement;canvas.addEventListener('pointermove',ev=>{if(ev.pointerType==='mouse')aimAt(worldAim(ev));});canvas.addEventListener('pointerdown',ev=>{if(ev.pointerType==='mouse'){mouseDown=true;aimAt(worldAim(ev));}});window.addEventListener('pointerup',()=>mouseDown=false);
